-- Generated by Loom
-- Generator: satellite
-- Variant: non_historised
-- Hash function: sha256
{{ config(materialized='incremental', incremental_strategy='append') }}
WITH staged AS (
    SELECT
        LOWER(sha256(concat(LOWER(sha256(UPPER(TRIM(CAST(s.order_id AS VARCHAR))))), LOWER(sha256(UPPER(TRIM(CAST(s.customer_id AS VARCHAR)))))))) AS order_customer_hk,
        LOWER(sha256(concat(COALESCE(CAST(s.product_name AS VARCHAR), '~'), '|', COALESCE(CAST(s.quantity AS VARCHAR), '~')))) AS __hash_diff,
        s.product_name,
        s.quantity,
        localtimestamp AS __loaded_at,
        'pos' AS __record_source
    FROM {{ ref('stg_order_items') }} AS s
    JOIN {{ ref('link_order_customer') }} AS p
        ON LOWER(sha256(concat(LOWER(sha256(UPPER(TRIM(CAST(s.order_id AS VARCHAR))))), LOWER(sha256(UPPER(TRIM(CAST(s.customer_id AS VARCHAR)))))))) = p.order_customer_hk
)
SELECT
    st.order_customer_hk,
    st.product_name,
    st.quantity,
    st.__loaded_at,
    st.__record_source
FROM staged AS st
{% if is_incremental() %}
WHERE NOT EXISTS (
    SELECT 1
    FROM {{ this }} AS t
    WHERE t.order_customer_hk = st.order_customer_hk
      AND LOWER(sha256(concat(COALESCE(CAST(t.product_name AS VARCHAR), '~'), '|', COALESCE(CAST(t.quantity AS VARCHAR), '~')))) = st.__hash_diff
)
{% endif %}
